interface Message { routingKey: string; metadata: any }
interface RoutePlan { queue: string; weight?: number }
interface RouterStrategy { route(msg: Message): RoutePlan[] }

class StrategyRegistry {
  private map = new Map<string, RouterStrategy>();
  register(name: string, s: RouterStrategy) { this.map.set(name, s) }
  get(name: string): RouterStrategy | undefined { return this.map.get(name) }
